const hook = $('Webhook (chat)').first().json;

const raw =
  typeof hook.imageUrl === 'string' && hook.imageUrl.trim() !== '' ? hook.imageUrl
  : (typeof hook.base64Image === 'string' && hook.base64Image.trim() !== '' ? hook.base64Image
  : '');
const dataUrl = raw.startsWith('data:') ? raw : '';

const scanId = typeof hook.scanId === 'string' && hook.scanId.trim() !== '' ? hook.scanId : 'chat'; 
const message = typeof hook.message === 'string' ? hook.message : '';
const history = Array.isArray(hook.history) ? hook.history : [];

return [{ json: {
  ...hook,
  scanId,
  message,
  history,
  url: dataUrl ? '' : raw,
  dataUrl,
  imageUrl: raw
} }];

const resolved = $('Resolve image').first().json;
const prepared = $('Prepare agent input').first().json;

const input = $input.all()[0];
const hasBinary = !!(input && input.binary && Object.keys(input.binary).length > 0);

if (hasBinary) {
  return [{ json: prepared, binary: input.binary }];
}

if (resolved.dataUrl) {
  const match = /^data:([^;]+);base64,(.+)$/.exec(resolved.dataUrl);
  if (match) {
    const mime = match[1] || 'image/jpeg';
    const b64 = match[2];
    return [{ json: prepared, binary: { data: {
      data: b64,
      mimeType: mime,
      fileName: prepared.imageUrl.split('/').pop() || 'plant.jpg'
    } } }];
  }
}

throw new Error('No image received. Webhook keys: ' + Object.keys($('Webhook (chat)').first().json).join(', '));

const resolved = $('Resolve image').first().json;
const message = resolved.message;
const history = resolved.history || [];

// Serialize any frontend-supplied history so long-lived context carries even if
// the n8n memory node was cleared. The memory node (keyed by scanId) is the
// primary conversation store; history here is a safety net of prior exchanges.
const historyText = history
  .map((m) => (m.role === 'assistant' ? 'المساعد: ' : 'المستخدم: ') + String(m.content || ''))
  .join('\n');

const chatInput = historyText
  ? 'محادثة حديثة:\n' + historyText + '\n\nالمستخدم يسأل الآن: ' + message
  : message;

return [{ json: {
  chatInput,
  scanId: resolved.scanId,
  imageUrl: resolved.imageUrl
} }];

const raw = $input.all()[0].json;
const reply = typeof raw.output === 'string'
  ? raw.output
  : (typeof raw.reply === 'string' ? raw.reply
  : (typeof raw.output === 'object' && raw.output && typeof raw.output.reply === 'string' ? raw.output.reply : ''));

if (!String(reply).trim()) {
  throw new Error('No reply from model. Raw: ' + JSON.stringify(raw).slice(0, 400));
}
return [{ json: { reply: String(reply) } }];
